// Builds css/tokens.css and tokens/tokens.ts from tokens/tokens.json.
// Run: npm run tokens   (never edit the generated files by hand)
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const T = JSON.parse(readFileSync(join(root, 'tokens/tokens.json'), 'utf8'));
const C = T.choice;
const head = `/* GENERATED by design-system/scripts/build-tokens.mjs from tokens.json. Do not edit. */\n`;

const pal = (p) => `  --ground: ${p.ground};\n  --surface: ${p.surface};\n  --ink: ${p.ink};\n  --muted: ${p.muted};\n  --primary: ${p.primary};\n  --on-primary: ${p.onPrimary};\n  --accent: ${p.accent};\n  --deep: ${p.deep};\n  --deep-ink: ${p.deepInk};\n  --eyebrow: ${p.eyebrow};`;
const kebab = (s) => s.replace(/[A-Z]/g, (m) => '-' + m.toLowerCase());
const fp = T.font.pairs[C.fontPair];
const rad = T.radius.styles[C.corners];

let css = head + `@import url('https://fonts.googleapis.com/css2?${fp.google}&display=swap');\n\n:root {\n  /* palette: ${C.palette} */\n${pal(T.color.palettes[C.palette])}\n`;
for (const [k, v] of Object.entries(T.color.status)) css += `  --${kebab(k)}: ${v};\n`;
for (const [k, v] of Object.entries(T.color.extra)) css += `  --${kebab(k)}: ${v};\n`;
css += `\n  /* fonts: ${C.fontPair} */\n  --font-display: '${fp.display}', ${T.font.fallback.display};\n  --font-text: '${fp.text}', ${T.font.fallback.text};\n  --display-weight: ${fp.displayWeight};\n`;
for (const [k, s] of Object.entries(T.font.scale)) css += `  --type-${k}-size: ${s.size}px;\n  --type-${k}-line: ${s.line};\n`;
css += `\n  /* spacing (4-pt scale) */\n`;
for (const [k, v] of Object.entries(T.space)) css += `  --space-${k}: ${v}px;\n`;
css += `\n  /* corners: ${C.corners} */\n`;
for (const [k, v] of Object.entries(rad)) css += `  --radius-${k}: ${v}px;\n`;
css += `\n  /* elevation */\n`;
for (const k of ['0', '1', '2', '3']) css += `  --elevation-${k}: ${T.elevation[k]};\n`;
css += `\n  /* layout */\n  --margin: ${T.layout.margin}px;\n  --gap-cards: ${T.layout.gapCards}px;\n  --gap-sections: ${T.layout.gapSections}px;\n  --header: ${T.layout.header}px;\n  --tab-bar: ${T.layout.tabBar}px;\n  --bag-bar: ${T.layout.bagBar}px;\n  --touch-min: ${T.layout.touchMin}px;\n`;
const f = T.motion.personalities[C.motion];
css += `\n  /* motion: ${C.motion} (×${f}) */\n`;
for (const [k, v] of Object.entries(T.motion.duration)) css += `  --dur-${k}: ${Math.round(v * f)}ms;\n`;
for (const [k, v] of Object.entries(T.motion.easing)) css += `  --ease-${k}: ${v};\n`;
css += `\n  /* seasonal skin (default = everyday) */\n`;
const skin = (s) => `  --skin-hero-bg: ${s.heroBg};\n  --skin-hero-ink: ${s.heroInk};\n  --skin-eyebrow: ${s.eyebrow};\n  --skin-accent: ${s.accent};\n  --skin-tint: ${s.tint};\n`;
css += skin(T.themes.skins.base) + `}\n\n`;
css += `/* dark mode: ${C.darkPalette}. Shadows become fine outlines. */\n[data-mode='dark'] {\n${pal(T.color.palettes[C.darkPalette])}\n  --line: rgba(242,232,219,0.12);\n  --tint: #29201B;\n  --elevation-1: ${T.elevation.darkBorder};\n}\n@media (prefers-color-scheme: dark) { :root:not([data-mode='light']) {\n${pal(T.color.palettes[C.darkPalette])}\n  --line: rgba(242,232,219,0.12);\n  --tint: #29201B;\n  --elevation-1: ${T.elevation.darkBorder};\n} }\n\n`;
css += `/* seasonal and holiday skins: set <html data-skin="…"> from themes/calendar.ts */\n`;
for (const [k, s] of Object.entries(T.themes.skins)) if (k !== 'base') css += `[data-skin='${k}'] {\n${skin(s)}}\n`;
css += `\n/* type scale */\n`;
for (const [k, s] of Object.entries(T.font.scale)) {
  css += `.t-${k} { font-family: var(--font-${s.family}); font-size: var(--type-${k}-size); line-height: var(--type-${k}-line); font-weight: ${s.family === 'display' && k === 'display' ? 'var(--display-weight)' : s.weight}; letter-spacing: ${s.tracking}px;${s.uppercase ? ' text-transform: uppercase;' : ''} }\n`;
}
css += `\n/* accessibility */\n:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }\n@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation-duration: 1ms !important; animation-iteration-count: 1 !important; transition-duration: 1ms !important; } }\n`;
writeFileSync(join(root, 'css/tokens.css'), css);

const ts = `// GENERATED by design-system/scripts/build-tokens.mjs from tokens.json. Do not edit.\nexport const tokens = ${JSON.stringify(T, null, 2)} as const;\nexport type Tokens = typeof tokens;\nexport type SkinId = keyof typeof tokens.themes.skins;\nexport type PaletteId = keyof typeof tokens.color.palettes;\nexport type Outfit = (typeof tokens.mascot.outfits)[number];\nexport type PoseId = (typeof tokens.mascot.poses)[number];\nexport default tokens;\n`;
writeFileSync(join(root, 'tokens/tokens.ts'), ts);
console.log(`tokens: palette=${C.palette}, fonts=${C.fontPair}, corners=${C.corners}, motion=${C.motion} → css/tokens.css, tokens/tokens.ts`);
